code_sketch:
/* forwarder */
uint32_t n = htonl(len);
struct iovec v[2] = {{&n, sizeof n}, {body, len}};
if (writev(peer_fd, v, 2) < 0) return -1;          /* short writes still possible */

/* receiver */
while (recv_full(fd, &n, sizeof n) == 0) {
    size_t len = ntohl(n);
    if (len > MAX_MSG) return -1;                   /* bound before allocating */
    recv_full(fd, body, len);
    dispatch(tag_of(body))(body);                   /* peer handler by type tag */
}
